/*
 * Quizzy application-specific additions on top of quizzy.css.
 */

.option-row {
  position: relative;
}

.preview-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-top: 24px;
}

.preview-banner__actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.play-option[disabled] {
  cursor: default;
}

