module ApplicationHelper
  def option_letter(index)
    result = +""
    n = index
    loop do
      result.prepend((65 + (n % 26)).chr)
      n = (n / 26) - 1
      break if n < 0
    end
    result
  end

  def format_points(points)
    points == 1 ? "1 point" : "#{points} points"
  end

  def format_timer_seconds(total_seconds)
    secs = [ total_seconds.to_i, 0 ].max
    format("%d:%02d", secs / 60, secs % 60)
  end
end
