  </header>

  <main class="screen__body" data-moderator-game-target="stage">
    <% case @state[:status] %>
    <% when "lobby" %>
      <div class="lobby">
        <div>
          <h1 class="lobby__title"><%= @quiz.title %></h1>
          <div class="lobby__join">Join at</div>
          <div class="lobby__url"><%= @join_url %></div>
          <div class="counter-pill"><span>Players: <strong data-role="players-count"><%= @state[:players_count] %></strong></span></div>
        </div>
        <div class="qr"><%= @qr_svg.html_safe %></div>
      </div>

    <% when "question_open" %>
      <% q = @state[:question] %>
      <div class="stage-question">
        <div class="stage-question__num">Question <%= q[:number] %> of <%= q[:total] %></div>
        <div class="stage-question__body"><%= q[:body] %></div>
        <ol class="stage-options">
          <% q[:options].each do |opt| %>
            <li class="stage-option">
              <span class="stage-option__letter" aria-hidden="true"><%= opt[:letter] %></span>
              <span class="stage-option__title"><%= opt[:body] %></span>
            </li>
          <% end %>
        </ol>
      </div>

    <% when "question_closed" %>
      <% q = @state[:question] %>
      <div class="stage-question">
        <div class="stage-question__num">Question <%= q[:number] %> of <%= q[:total] %></div>
        <div class="stage-question__body"><%= q[:body] %></div>
        <ol class="stage-options stage-options--results">
          <% q[:options].each do |opt| %>
            <li class="stage-option <%= 'is-correct' if opt[:correct] %>"<%= ' data-correct="true"'.html_safe if opt[:correct] %>>
              <span class="stage-option__bar" style="--share: <%= opt[:share] %>%" aria-hidden="true"></span>
              <span class="stage-option__letter" aria-hidden="true"><%= opt[:letter] %></span>
              <span class="stage-option__title"><%= opt[:body] %></span>
              <% if opt[:correct] %>
                <span class="stage-option__mark">Correct</span>
              <% end %>
              <span class="stage-option__count"><%= opt[:count] %></span>
            </li>
          <% end %>
        </ol>
      </div>

    <% when "finished" %>
      <div class="leaderboard-layout">
        <div>
          <div class="screen__kicker"><%= @quiz.title %></div>
          <h1 class="leaderboard-layout__title">The quiz is over</h1>
        </div>
        <% if @state[:leaderboard].any? %>
          <ol class="leaderboard" data-role="leaderboard">
            <% @state[:leaderboard].each do |entry| %>
              <li class="leader <%= 'is-winner' if entry[:winner] %> <%= 'is-tied' if entry[:tied_at_cutoff] %>"
                  data-player-id="<%= entry[:player_id] %>">
                <span class="leader__place"><%= entry[:place] %></span>
                <span class="leader__identity">
                  <span class="leader__name"><%= entry[:name] %></span><% if entry[:winner] %> <span class="leader__badge">Winner</span><% end %>
                </span>
                <span class="leader__score"><%= format_points(entry[:points]) %></span>
              </li>
            <% end %>
          </ol>
        <% else %>
          <p class="play-lead" data-role="leaderboard-empty">No players joined this game.</p>
        <% end %>
      </div>
    <% end %>
  </main>

  <footer class="screen-controls">
    <div class="screen-controls__info" data-moderator-game-target="controlsInfo">
      <%= link_to "← Back to quiz", moderate_quiz_path(@quiz) %>
    </div>
    <div class="buttons" data-moderator-game-target="controlsAction">
      <% case @state[:status] %>
      <% when "lobby" %>
        <button type="button" class="btn btn--light" data-action="moderator-game#start">Start</button>
      <% when "question_open" %>
        <button type="button" class="btn btn--pink" data-action="moderator-game#finish">Finish</button>
      <% when "question_closed" %>
        <% if @state[:question][:is_last] %>
          <button type="button" class="btn btn--pink" data-action="moderator-game#endGame">End quiz</button>
        <% else %>
          <button type="button" class="btn btn--light" data-action="moderator-game#nextQuestion">Next</button>
        <% end %>
      <% when "finished" %>
        <button type="button" class="btn btn--pink" data-action="moderator-game#pickTopWinners">Top <%= @state[:winners_count] %></button>
        <button type="button" class="btn btn--light" data-action="moderator-game#drawWinners">Draw</button>
        <button type="button" class="btn btn--ghost-light" data-action="moderator-game#resetWinners">Reset winners</button>
      <% end %>
    </div>
  </footer>
</div>
EOF

cat <<'EOF' > app/javascript/controllers/moderator_game_controller.js
import { Controller } from "@hotwired/stimulus"
import { createConsumer } from "@rails/actioncable"

export default class extends Controller {
  static targets = ["screen", "topMeta", "stage", "controlsInfo", "controlsAction", "qrTemplate"]
  static values = {
    gameId: Number,
    token: String,
    initialState: Object,
    stateUrl: String,
    startUrl: String,
    finishUrl: String,
    nextUrl: String,
    endUrl: String,
    pickTopUrl: String,
    drawUrl: String,
    resetWinnersUrl: String,
    quizUrl: String,
    joinUrl: String
  }

  connect() {
    this.state = this.initialStateValue || {}
    this.renderedKey = this.viewKey(this.state)
    this.cableConnected = false
    this.actionInFlight = false
    this.pollTimer = null
    this.connectGraceTimer = null
    this.timerQuestionId = null
    this.timerDeadlineMs = null
    this.timerInterval = null
    this.timerFallbackTimeout = null
    this.lastRenderedTimerSeconds = null

    this.handleOnline = () => this.recoverConnection()
    this.handleVisibility = () => {
      if (document.visibilityState === "visible") this.recoverConnection()
    }
    this.handlePageShow = (event) => {
      if (event.persisted) this.recoverConnection()
    }

    window.addEventListener("online", this.handleOnline)
    document.addEventListener("visibilitychange", this.handleVisibility)
    window.addEventListener("pageshow", this.handlePageShow)

    this.syncQuestionTimer(this.state)

    this.connectCable()
    this.connectGraceTimer = setTimeout(() => {
      if (!this.cableConnected) {
        this.startPolling()
      }
    }, 2500)
  }

  disconnect() {
    this.stopQuestionTimer()
    this.stopConnectGrace()
    this.stopPolling()
    window.removeEventListener("online", this.handleOnline)
    document.removeEventListener("visibilitychange", this.handleVisibility)
    window.removeEventListener("pageshow", this.handlePageShow)

    if (this.subscription) {
      this.subscription.unsubscribe()
      this.subscription = null
    }
    if (this.consumer) {
      this.consumer.disconnect()
      this.consumer = null
    }
  }

  connectCable() {
    const wsUrl = `${window.location.origin.replace(/^http/, "ws")}/cable`
    this.consumer = createConsumer(wsUrl)
    this.subscription = this.consumer.subscriptions.create(
      {
        channel: "ModeratorChannel",
        game_id: this.gameIdValue,
        token: this.tokenValue
      },
      {
        connected: () => {
          this.cableConnected = true
          this.stopConnectGrace()
          this.stopPolling()
        },
        disconnected: () => {
          this.cableConnected = false
          this.startPolling()
        },
        received: (data) => {
          this.applyState(data)
        }
      }
    )
  }

  stopConnectGrace() {
    if (this.connectGraceTimer) {
      clearTimeout(this.connectGraceTimer)
      this.connectGraceTimer = null
    }
  }

  recoverConnection() {
    if (this.consumer) {
      const conn = this.consumer.connection
      if (!conn.isOpen() || conn.monitor.connectionIsStale()) {
        conn.reopen()
      }
    }
    this.syncState()
  }

  startPolling() {
    if (this.pollTimer) return
    this.pollTimer = setInterval(() => this.syncState(), 1500)
  }

  stopPolling() {
    if (this.pollTimer) {
      clearInterval(this.pollTimer)
      this.pollTimer = null
    }
  }

  async syncState() {
    try {
      const url = new URL(this.stateUrlValue, window.location.origin).href
      const response = await fetch(url, {
        headers: { "Accept": "application/json" },
        credentials: "same-origin",
        cache: "no-store"
      })
      if (!response.ok) return
      const data = await response.json()
      this.applyState(data)
    } catch {
      // Transient network error; next poll/reconnect will retry
    }
  }

  start() {
    this.postTransition(this.startUrlValue)
  }

  finish() {
    this.postTransition(this.finishUrlValue, {
      expected_question_id: this.state.question?.id
    })
  }

  nextQuestion() {
    this.postTransition(this.nextUrlValue, {
      expected_question_id: this.state.question?.id
    })
  }

  endGame() {
    this.postTransition(this.endUrlValue, {
      expected_question_id: this.state.question?.id
    })
  }

  pickTopWinners() {
    this.postTransition(this.pickTopUrlValue)
  }

  drawWinners() {
    this.postTransition(this.drawUrlValue)
  }

  resetWinners() {
    this.postTransition(this.resetWinnersUrlValue)
  }

  async postTransition(path, payload = {}) {
    if (this.actionInFlight) return
    this.actionInFlight = true
    this.setActionButtonsDisabled(true)

    try {
      const csrfToken = document.querySelector("meta[name='csrf-token']")?.content || ""
      const url = new URL(path, window.location.origin).href
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json",
          "X-CSRF-Token": csrfToken
        },
        credentials: "same-origin",
        body: JSON.stringify(payload)
      })

      if (response.ok) {
        const data = await response.json()
        this.applyState(data)
      } else {
        await this.syncState()
      }
    } catch {
      await this.syncState()
    } finally {
      this.actionInFlight = false
      this.setActionButtonsDisabled(false)
    }
  }

  setActionButtonsDisabled(disabled) {
    if (!this.hasControlsActionTarget) return
    this.controlsActionTarget.querySelectorAll("button").forEach((btn) => {
      btn.disabled = disabled
    })
  }

  stateRank(state) {
    if (!state || !state.status) return [-1, 0]
    switch (state.status) {
      case "lobby":
        return [0, 0]
      case "question_open":
        return [state.question?.number || 1, 1]
      case "question_closed":
        return [state.question?.number || 1, 2]
      case "finished":
        return [Number.MAX_SAFE_INTEGER, state.winners_version || 0]
      default:
        return [-1, 0]
    }
  }

  compareRank(a, b) {
    if (a[0] !== b[0]) return a[0] - b[0]
    return a[1] - b[1]
  }

  viewKey(state) {
    if (!state || !state.status) return ""
    if (state.status === "question_open" || state.status === "question_closed") {
      return `${state.status}:${state.question?.id}`
    }
    return state.status
  }

  formatPoints(points) {
    return points === 1 ? "1 point" : `${points} points`
  }

  formatTimer(totalSeconds) {
    const secs = Math.max(0, Math.floor(totalSeconds))
    const minutes = Math.floor(secs / 60)
    const seconds = secs % 60
    return `${minutes}:${String(seconds).padStart(2, "0")}`
  }

  syncQuestionTimer(state) {
    if (state.status !== "question_open" || !state.timer || !state.question) {
      this.stopQuestionTimer()
      return
    }

    const questionId = state.question.id
    const remainingMs = Math.max(0, Number(state.timer.remaining_ms) || 0)
    const candidateDeadline = performance.now() + remainingMs

    if (this.timerQuestionId !== questionId || this.timerDeadlineMs === null) {
      this.stopQuestionTimer()
      this.timerQuestionId = questionId
      this.timerDeadlineMs = candidateDeadline
    } else {
      this.timerDeadlineMs = Math.min(this.timerDeadlineMs, candidateDeadline)
    }

    this.updateTimerDisplay()

    if (remainingMs <= 0) {
      this.scheduleExpiredSync()
    } else {
      this.startTimerLoop()
    }
  }

  updateTimerDisplay() {
    if (this.timerDeadlineMs === null) return

    const remainingMs = Math.max(0, this.timerDeadlineMs - performance.now())
    const displaySeconds = Math.ceil(remainingMs / 1000)

    const el = this.topMetaTarget.querySelector("[data-role='question-timer']")
    if (el && displaySeconds !== this.lastRenderedTimerSeconds) {
      el.textContent = this.formatTimer(displaySeconds)
      el.classList.toggle("is-urgent", displaySeconds <= 5)
      this.lastRenderedTimerSeconds = displaySeconds
    }

    if (remainingMs <= 0) {
      this.stopTimerLoop()
      this.scheduleExpiredSync()
    }
  }

  startTimerLoop() {
    if (this.timerInterval) return
    this.timerInterval = setInterval(() => this.updateTimerDisplay(), 100)
  }

  stopTimerLoop() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval)
      this.timerInterval = null
    }
  }

  scheduleExpiredSync() {
    if (this.timerFallbackTimeout) return
    const expectedQuestionId = this.timerQuestionId
    this.timerFallbackTimeout = setTimeout(async () => {
      this.timerFallbackTimeout = null
      if (this.state.status !== "question_open" || this.state.question?.id !== expectedQuestionId) {
        return
      }
      await this.syncState()
      if (this.state.status === "question_open" && this.state.question?.id === expectedQuestionId) {
        const remainingMs = Math.max(0, (this.timerDeadlineMs ?? 0) - performance.now())
        if (remainingMs <= 0) {
          this.scheduleExpiredSync()
        }
      }
    }, 200)
  }

  stopQuestionTimer() {
    this.stopTimerLoop()
    if (this.timerFallbackTimeout) {
      clearTimeout(this.timerFallbackTimeout)
      this.timerFallbackTimeout = null
    }
    this.timerQuestionId = null
    this.timerDeadlineMs = null
    this.lastRenderedTimerSeconds = null
  }

  applyState(nextState) {
    if (!nextState || !nextState.status) return
    if (this.compareRank(this.stateRank(nextState), this.stateRank(this.state)) < 0) {
      return
    }

    this.state = nextState
    const nextKey = this.viewKey(nextState)

    if (nextKey === this.renderedKey) {
      if (nextState.status === "finished") {
        this.updateFinishedLeaderboard(nextState)
      } else {
        this.updateLiveCounters(nextState)
        this.syncQuestionTimer(nextState)
      }
      return
    }

    this.renderedKey = nextKey
    this.renderFull(nextState)
    this.syncQuestionTimer(nextState)
  }

  updateLiveCounters(state) {
    if (state.status === "lobby") {
      const el = this.stageTarget.querySelector("[data-role='players-count']")
      if (el) {
        const count = state.players_count ?? state.active_players_count ?? 0
        el.textContent = String(count)
      }
    } else if (state.status === "question_open") {
      const el = this.topMetaTarget.querySelector("[data-role='answers-counter']")
      if (el) {
        const answered = state.answers_count ?? 0
        const active = state.active_players_count ?? 0
        el.textContent = `Answers: ${answered} / ${active}`
      }
    }
  }

  updateFinishedLeaderboard(state) {
    const entries = state.leaderboard || []
    const list = this.stageTarget.querySelector("[data-role='leaderboard']")

    if (!list) {
      if (entries.length > 0) {
        this.renderStage(state)
      }
      return
    }

    const items = Array.from(list.querySelectorAll("li.leader"))
    const sameOrder =
      items.length === entries.length &&
      entries.every((entry, idx) => Number(items[idx].dataset.playerId) === entry.player_id)

    if (!sameOrder) {
      this.renderStage(state)
      return
    }

    entries.forEach((entry, idx) => {
      const li = items[idx]
      const wasWinner = li.classList.contains("is-winner")
      const isWinner = Boolean(entry.winner)

      li.classList.toggle("is-tied", Boolean(entry.tied_at_cutoff))

      if (wasWinner !== isWinner) {
        li.classList.toggle("is-winner", isWinner)
        const identity = li.querySelector(".leader__identity")
        if (identity) {
          const existingBadge = identity.querySelector(".leader__badge")
          if (isWinner && !existingBadge) {
            const badge = document.createElement("span")
            badge.className = "leader__badge"
            badge.textContent = "Winner"
            identity.append(document.createTextNode(" "), badge)
          } else if (!isWinner && existingBadge) {
            if (existingBadge.previousSibling && existingBadge.previousSibling.nodeType === Node.TEXT_NODE) {
              existingBadge.previousSibling.remove()
            }
            existingBadge.remove()
          }
        }
      }
    })
  }

  renderFull(state) {
    this.renderCoverClass(state.status)
    this.renderTopMeta(state)
    this.renderStage(state)
    this.renderControlsAction(state)
  }

  renderCoverClass(status) {
    if (status === "lobby") {
      this.screenTarget.className = "screen cover"
    } else if (status === "finished") {
      this.screenTarget.className = "screen cover cover--night"
    } else {
      this.screenTarget.className = "screen cover cover--blue"
    }
  }

  renderTopMeta(state) {
    this.topMetaTarget.replaceChildren()
    if (state.status === "question_open") {
      if (state.timer) {
        const remainingMs = Math.max(0, Number(state.timer.remaining_ms) || 0)
        const secs = Math.ceil(remainingMs / 1000)
        const timerEl = document.createElement("div")
        timerEl.className = secs <= 5 ? "question-timer is-urgent" : "question-timer"
        timerEl.dataset.role = "question-timer"
        timerEl.textContent = this.formatTimer(secs)
        this.topMetaTarget.appendChild(timerEl)
      }

      const counter = document.createElement("div")
      counter.className = "answers-counter"
      counter.dataset.role = "answers-counter"
      counter.textContent = `Answers: ${state.answers_count ?? 0} / ${state.active_players_count ?? 0}`
      this.topMetaTarget.appendChild(counter)
    } else if (state.status === "question_closed" || state.status === "finished") {
      const title = document.createElement("div")
      title.className = "screen__quiz-title"
      title.textContent = state.quiz_title || ""
      this.topMetaTarget.appendChild(title)
    }
  }

  renderStage(state) {
    this.stageTarget.replaceChildren()

    if (state.status === "lobby") {
      const lobby = document.createElement("div")
      lobby.className = "lobby"

      const left = document.createElement("div")
      const title = document.createElement("h1")
      title.className = "lobby__title"
      title.textContent = state.quiz_title || ""

      const joinLabel = document.createElement("div")
      joinLabel.className = "lobby__join"
      joinLabel.textContent = "Join at"

      const joinUrl = document.createElement("div")
      joinUrl.className = "lobby__url"
      joinUrl.textContent = this.joinUrlValue

      const pill = document.createElement("div")
      pill.className = "counter-pill"
      const pillSpan = document.createElement("span")
      pillSpan.append(document.createTextNode("Players: "))
      const strong = document.createElement("strong")
      strong.dataset.role = "players-count"
      strong.textContent = String(state.players_count ?? state.active_players_count ?? 0)
      pillSpan.appendChild(strong)
      pill.appendChild(pillSpan)

      left.append(title, joinLabel, joinUrl, pill)

      const qr = document.createElement("div")
      qr.className = "qr"
      if (this.hasQrTemplateTarget) {
        qr.appendChild(this.qrTemplateTarget.content.cloneNode(true))
      }

      lobby.append(left, qr)
      this.stageTarget.appendChild(lobby)
      return
    }

    if (state.status === "question_open" && state.question) {
      const q = state.question
      const wrap = document.createElement("div")
      wrap.className = "stage-question"

      const num = document.createElement("div")
      num.className = "stage-question__num"
      num.textContent = `Question ${q.number} of ${q.total}`

      const body = document.createElement("div")
      body.className = "stage-question__body"
      body.textContent = q.body

      const list = document.createElement("ol")
      list.className = "stage-options"

      q.options.forEach((opt) => {
        const li = document.createElement("li")
        li.className = "stage-option"

        const letter = document.createElement("span")
        letter.className = "stage-option__letter"
        letter.setAttribute("aria-hidden", "true")
        letter.textContent = opt.letter

        const optTitle = document.createElement("span")
        optTitle.className = "stage-option__title"
        optTitle.textContent = opt.body

        li.append(letter, optTitle)
        list.appendChild(li)
      })

      wrap.append(num, body, list)
      this.stageTarget.appendChild(wrap)
      return
    }

    if (state.status === "question_closed" && state.question) {
      const q = state.question
      const wrap = document.createElement("div")
      wrap.className = "stage-question"

      const num = document.createElement("div")
      num.className = "stage-question__num"
      num.textContent = `Question ${q.number} of ${q.total}`

      const body = document.createElement("div")
      body.className = "stage-question__body"
      body.textContent = q.body

      const list = document.createElement("ol")
      list.className = "stage-options stage-options--results"

      q.options.forEach((opt) => {
        const li = document.createElement("li")
        li.className = opt.correct ? "stage-option is-correct" : "stage-option"
        if (opt.correct) li.dataset.correct = "true"

        const bar = document.createElement("span")
        bar.className = "stage-option__bar"
        bar.style.setProperty("--share", `${opt.share ?? 0}%`)
        bar.setAttribute("aria-hidden", "true")

        const letter = document.createElement("span")
        letter.className = "stage-option__letter"
        letter.setAttribute("aria-hidden", "true")
        letter.textContent = opt.letter

        const optTitle = document.createElement("span")
        optTitle.className = "stage-option__title"
        optTitle.textContent = opt.body

        li.append(bar, letter, optTitle)

        if (opt.correct) {
          const mark = document.createElement("span")
          mark.className = "stage-option__mark"
          mark.textContent = "Correct"
          li.appendChild(mark)
        }

        const count = document.createElement("span")
        count.className = "stage-option__count"
        count.textContent = String(opt.count ?? 0)
        li.appendChild(count)

        list.appendChild(li)
      })

      wrap.append(num, body, list)
      this.stageTarget.appendChild(wrap)
      return
    }

    if (state.status === "finished") {
      const layout = document.createElement("div")
      layout.className = "leaderboard-layout"

      const heading = document.createElement("div")
      const kicker = document.createElement("div")
      kicker.className = "screen__kicker"
      kicker.textContent = state.quiz_title || ""

      const title = document.createElement("h1")
      title.className = "leaderboard-layout__title"
      title.textContent = "The quiz is over"

      heading.append(kicker, title)
      layout.appendChild(heading)

      const entries = state.leaderboard || []
      if (entries.length > 0) {
        const list = document.createElement("ol")
        list.className = "leaderboard"
        list.dataset.role = "leaderboard"

        entries.forEach((entry) => {
          list.appendChild(this.buildLeaderboardItem(entry))
        })

        layout.appendChild(list)
      } else {
        const empty = document.createElement("p")
        empty.className = "play-lead"
        empty.dataset.role = "leaderboard-empty"
        empty.textContent = "No players joined this game."
        layout.appendChild(empty)
      }

      this.stageTarget.appendChild(layout)
    }
  }

  buildLeaderboardItem(entry) {
    const li = document.createElement("li")
    const classes = ["leader"]
    if (entry.winner) classes.push("is-winner")
    if (entry.tied_at_cutoff) classes.push("is-tied")
    li.className = classes.join(" ")
    li.dataset.playerId = String(entry.player_id)

    const place = document.createElement("span")
    place.className = "leader__place"
    place.textContent = String(entry.place)

    const identity = document.createElement("span")
    identity.className = "leader__identity"

    const name = document.createElement("span")
    name.className = "leader__name"
    name.textContent = entry.name

    identity.appendChild(name)

    if (entry.winner) {
      const badge = document.createElement("span")
      badge.className = "leader__badge"
      badge.textContent = "Winner"
      identity.append(document.createTextNode(" "), badge)
    }

    const score = document.createElement("span")
    score.className = "leader__score"
    score.textContent = this.formatPoints(entry.points ?? 0)

    li.append(place, document.createTextNode(" "), identity, document.createTextNode(" "), score)
    return li
  }

  renderControlsAction(state) {
    this.controlsActionTarget.replaceChildren()

    if (state.status === "finished") {
      const n = state.winners_count || 3

      const topBtn = document.createElement("button")
      topBtn.type = "button"
      topBtn.className = "btn btn--pink"
      topBtn.textContent = `Top ${n}`
      topBtn.addEventListener("click", () => this.pickTopWinners())

      const drawBtn = document.createElement("button")
      drawBtn.type = "button"
      drawBtn.className = "btn btn--light"
      drawBtn.textContent = "Draw"
      drawBtn.addEventListener("click", () => this.drawWinners())

      const resetBtn = document.createElement("button")
      resetBtn.type = "button"
      resetBtn.className = "btn btn--ghost-light"
      resetBtn.textContent = "Reset winners"
      resetBtn.addEventListener("click", () => this.resetWinners())

      this.controlsActionTarget.append(topBtn, drawBtn, resetBtn)
      return
    }

    let label = null
    let btnClass = "btn btn--light"
    let handler = null

    if (state.status === "lobby") {
      label = "Start"
      btnClass = "btn btn--light"
      handler = () => this.start()
    } else if (state.status === "question_open") {
      label = "Finish"
      btnClass = "btn btn--pink"
      handler = () => this.finish()
    } else if (state.status === "question_closed" && state.question) {
      if (state.question.is_last) {
        label = "End quiz"
        btnClass = "btn btn--pink"
        handler = () => this.endGame()
      } else {
        label = "Next"
        btnClass = "btn btn--light"
        handler = () => this.nextQuestion()
      }
    }

    if (label && handler) {
      const btn = document.createElement("button")
      btn.type = "button"
      btn.className = btnClass
      btn.textContent = label
      btn.addEventListener("click", handler)
      this.controlsActionTarget.appendChild(btn)
    }
  }
}
